import{_ as p,a0 as o,w as d,s as r,ao as l,I as n,x as i,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 21 世紀該怎樣編譯 Linux 內核 | LCTT x X-CMD","titleTemplate":false,"description":"在 21 世紀該怎樣編譯 Linux 內核 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 21 世紀該怎樣編譯 Linux 內核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 21 世紀該怎樣編譯 Linux 內核 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190824 How to compile a Linux kernel in the 21st century","title":"在 21 世紀該怎樣編譯 Linux 內核","tag":"201910","desc":""},"relativePath":"201910/20190824 How to compile a Linux kernel in the 21st century.md","filePath":"[post].md"}'),u={name:"201910/20190824 How to compile a Linux kernel in the 21st century.md"};function g(h,s,k,b,f,m){const t=o("Link");return d(),r("div",null,[s[39]||(s[39]=l('<h1 id="在-21-世紀該怎樣編譯-linux-內核" tabindex="-1">在 21 世紀該怎樣編譯 Linux 內核 <a class="header-anchor" href="#在-21-世紀該怎樣編譯-linux-內核" aria-label="Permalink to “在 21 世紀該怎樣編譯 Linux 內核”">​</a></h1><blockquote><p>也許你並不需要編譯 Linux 內核，但你能通過這篇教程快速上手。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201910/06/113927vrs6rurljyuza8cy.jpg" alt=""></p><p>在計算機世界裏，<ruby>內核<rt>kernel</rt></ruby>是處理硬件與一般系統之間通信的<ruby>低階軟件<rt>low-level software</rt></ruby>。除過一些燒錄進計算機主板的初始固件，當你啓動計算機時，內核讓系統意識到它有一個硬盤驅動器、屏幕、鍵盤以及網卡。分配給每個部件相等時間（或多或少）使得圖像、音頻、文件系統和網絡可以流暢甚至並行地運行。</p><p>然而，對於硬件的需求是源源不斷的，隨着發佈的硬件越多，內核就必須納入更多代碼來保證那些硬件正常工作。得到具體的數字很困難，但是 Linux 內核無疑是硬件兼容性方面的頂級內核之一。Linux 操作着無數的計算機和移動電話、工業用途和愛好者使用的板級嵌入式系統（SoC）、RAID 卡、縫紉機等等。</p><p>回到 20 世紀（甚至是 21 世紀初期），對於 Linux 用户來説，在剛買到新的硬件後就需要下載最新的內核代碼並編譯安裝才能使用這是不可理喻的。而現在你也很難見到 Linux 用户為了好玩而編譯內核或通過高度專業化定製的硬件的方式賺錢。現在，通常已經不需要再編譯 Linux 內核了。</p><p>這裏列出了一些原因以及快速編譯內核的教程。</p><h3 id="更新當前的內核" tabindex="-1">更新當前的內核 <a class="header-anchor" href="#更新當前的內核" aria-label="Permalink to “更新當前的內核”">​</a></h3><p>無論你買了配備新顯卡或 Wifi 芯片集的新品牌電腦還是給家裏配備一個新的打印機，你的操作系統（稱為 GNU+Linux 或 Linux，它也是該內核的名字）需要一個驅動程序來打開新部件（顯卡、芯片集、打印機和其他任何東西）的信道。有時候當你插入某些新的設備時而你的電腦表示發現了它，這具有一定的欺騙性。別被騙到了，有時候那就夠了，但更多的情況是你的操作系統僅僅是使用了通用的協議檢測到安裝了新的設備。</p><p>例如，你的計算機也許能夠鑑別出新的網絡打印機，但有時候那僅僅是因為打印機的網卡被設計成為了獲得 DHCP 地址而在網絡上標識自己。它並不意味着你的計算機知道如何發送文檔給打印機進行打印。事實上，你可以認為計算機甚至不“知道”那台設備是一個打印機。它也許僅僅是顯示網絡有個設備在一個特定的地址上，並且該設備以一系列字符 “p-r-i-n-t-e-r” 標識自己而已。人類語言的便利性對於計算機毫無意義。計算機需要的是一個驅動程序。</p>',10)),n("p",null,[s[6]||(s[6]=i("內核開發者、硬件製造商、技術支持和愛好者都知道新的硬件會不斷地發佈。它們大多數都會貢獻驅動程序，直接提交給內核開發團隊以包含在 Linux 中。例如，英偉達顯卡驅動程序通常都會寫入 ",-1)),a(t,{href:"https://nouveau.freedesktop.org/wiki/"},{default:e(()=>[...s[0]||(s[0]=[i("Nouveau",-1)])]),_:1}),s[7]||(s[7]=i(" 內核模組中，並且因為英偉達顯卡很常用，它的代碼都包含在任一個日常使用的發行版內核中（例如當下載 ",-1)),a(t,{href:"http://fedoraproject.org"},{default:e(()=>[...s[1]||(s[1]=[i("Fedora",-1)])]),_:1}),s[8]||(s[8]=i(" 或 ",-1)),a(t,{href:"http://ubuntu.com"},{default:e(()=>[...s[2]||(s[2]=[i("Ubuntu",-1)])]),_:1}),s[9]||(s[9]=i(" 得到的內核）。英偉達也有不常用的地方，例如嵌入式系統中 Nouveau 模組通常被移除。對其他設備來説也有類似的模組：打印機得益於 ",-1)),a(t,{href:"https://wiki.linuxfoundation.org/openprinting/database/foomatic"},{default:e(()=>[...s[3]||(s[3]=[i("Foomatic",-1)])]),_:1}),s[10]||(s[10]=i(" 和 ",-1)),a(t,{href:"https://www.cups.org/"},{default:e(()=>[...s[4]||(s[4]=[i("CUPS",-1)])]),_:1}),s[11]||(s[11]=i("，無線網卡有 ",-1)),a(t,{href:"https://wireless.wiki.kernel.org/en/users/drivers"},{default:e(()=>[...s[5]||(s[5]=[i("b43、ath9k、wl",-1)])]),_:1}),s[12]||(s[12]=i(" 模組等等。",-1))]),s[40]||(s[40]=l(`<p>發行版往往會在它們 Linux 內核的構建中包含儘可能多合理的驅動程序，因為他們想讓你在接入新設備時不用安裝驅動程序能夠立即使用。對於大多數情況來説就是這樣的，尤其是現在很多設備廠商都在資助自己售賣硬件的 Linux 驅動程序開發，並且直接將這些驅動程序提交給內核團隊以用在通常的發行版上。</p><p>有時候，或許你正在運行六個月之前安裝的內核，並配備了上週剛剛上市令人興奮的新設備。在這種情況下，你的內核也許沒有那款設備的驅動程序。好消息是經常會出現那款設備的驅動程序已經存在於最近版本的內核中，意味着你只要更新運行的內核就可以了。</p><p>通常，這些都是通過安裝包管理軟件完成的。例如在 RHEL、CentOS 和 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update kernel</span></span></code></pre></div><p>在 Debian 和 Ubuntu 上，首先獲取你當前內核的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -r</span></span>
<span class="line"><span>4.4.186</span></span></code></pre></div><p>搜索新的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt search linux-image</span></span></code></pre></div><p>安裝找到的最新版本。在這個例子中，最新的版本是 5.2.4：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install linux-image-5.2.4</span></span></code></pre></div>`,10)),n("p",null,[s[14]||(s[14]=i("內核更新後，你必須 ",-1)),a(t,{href:"https://opensource.com/article/19/7/reboot-linux"},{default:e(()=>[...s[13]||(s[13]=[i("reboot",-1)])]),_:1}),s[15]||(s[15]=i(" （除非你使用 kpatch 或 kgraft）。這時，如果你需要的設備驅動程序包含在最新的內核中，你的硬件就會正常工作。",-1))]),s[41]||(s[41]=l(`<h3 id="安裝內核模組" tabindex="-1">安裝內核模組 <a class="header-anchor" href="#安裝內核模組" aria-label="Permalink to “安裝內核模組”">​</a></h3><p>有時候一個發行版沒有預計到用户會使用某個設備（或者該設備的驅動程序至少不足以包含在 Linux 內核中）。Linux 對於驅動程序採用模組化方式，因此儘管驅動程序沒有編譯進內核，但發行版可以推送單獨的驅動程序包讓內核去加載。儘管有些複雜但是非常有用，尤其是當驅動程序沒有包含進內核中而是在引導過程中加載，或是內核中的驅動程序相比模組化的驅動程序過期時。第一個問題可以用 “initrd” 解決（初始化 RAM 磁盤），這一點超出了本文的討論範圍，第二點通過 “kmod” 系統解決。</p><p>kmod 系統保證了當內核更新後，所有與之安裝的模組化驅動程序也得到更新。如果你手動安裝一個驅動程序，你就體驗不到 kmod 提供的自動化，因此只要能用 kmod 安裝包，就應該選擇它。例如，儘管英偉達驅動程序以 Nouveau 模組構建在內核中，但官方的驅動程序僅由英偉達發佈。你可以去網站上手動安裝英偉達旗下的驅動程序，下載 “.run” 文件，並運行提供的 shell 腳本，但在安裝了新的內核之後你必須重複相同的過程，因為沒有任何東西告訴包管理軟件你手動安裝了一個內核驅動程序。英偉達驅動着你的顯卡，手動更新英偉達驅動程序通常意味着你需要通過終端來執行更新，因為沒有顯卡驅動程序將無法顯示。</p><p><img src="https://opensource.com/sites/default/files/uploads/nvidia.jpg" alt="Nvidia configuration application" title="Nvidia configuration application"></p><p>然而，如果你通過 kmod 包安裝英偉達驅動程序，更新你的內核也會更新你的英偉達驅動程序。在 Fedora 和相關的發行版中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install kmod-nvidia</span></span></code></pre></div><p>在 Debian 和相關發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install nvidia-kernel-common nvidia-kernel-dkms nvidia-glx nvidia-xconfig nvidia-settings nvidia-vdpau-driver vdpau-va-driver</span></span></code></pre></div><p>這僅僅是一個例子，但是如果你真的要安裝英偉達驅動程序，你也必須屏蔽掉 Nouveau 驅動程序。參考你使用發行版的文檔獲取最佳的步驟吧。</p><h3 id="下載並安裝驅動程序" tabindex="-1">下載並安裝驅動程序 <a class="header-anchor" href="#下載並安裝驅動程序" aria-label="Permalink to “下載並安裝驅動程序”">​</a></h3><p>不是所有的東西都包含在內核中，也不是所有的東西都可以作為內核模組使用。在某些情況下，你需要下載一個由供應商編寫並綁定好的特殊驅動程序，還有一些情況，你有驅動程序，但是沒有配置驅動程序的前端界面。</p>`,11)),n("p",null,[s[18]||(s[18]=i("有兩個常見的例子是 HP 打印機和 ",-1)),a(t,{href:"https://linuxwacom.github.io"},{default:e(()=>[...s[16]||(s[16]=[i("Wacom",-1)])]),_:1}),s[19]||(s[19]=i(" 數位板。如果你有一台 HP 打印機，你可能有能夠和打印機通信的通用的驅動程序，甚至能夠打印出東西。但是通用的驅動程序卻不能為特定型號的打印機提供定製化的選項，例如雙面打印、校對、紙盒選擇等等。",-1)),a(t,{href:"https://developers.hp.com/hp-linux-imaging-and-printing"},{default:e(()=>[...s[17]||(s[17]=[i("HPLIP",-1)])]),_:1}),s[20]||(s[20]=i("（HP Linux 成像和打印系統）提供了選項來進行任務管理、調整打印設置、選擇可用的紙盒等等。",-1))]),s[42]||(s[42]=l('<p>HPLIP 通常包含在包管理軟件中；只要搜索“hplip”就行了。</p><p><img src="https://opensource.com/sites/default/files/uploads/hplip.jpg" alt="HPLIP in action" title="HPLIP in action"></p><p>同樣的，電子藝術家主要使用的數位板 Wacom 的驅動程序通常也包含在內核中，但是例如調整壓感和按鍵功能等設置只能通過默認包含在 GNOME 的圖形控制面板訪問。但也可以作為 KDE 上額外的程序包“kde-config-tablet”來訪問。</p><p>這裏也有幾個類似的個別例子，例如內核中沒有驅動程序，但是以 RPM 或 DEB 文件提供了可供下載並且通過包管理軟件安裝的 kmod 版本的驅動程序。</p><h3 id="打上補丁並編譯你的內核" tabindex="-1">打上補丁並編譯你的內核 <a class="header-anchor" href="#打上補丁並編譯你的內核" aria-label="Permalink to “打上補丁並編譯你的內核”">​</a></h3><p>即使在 21 世紀的未來主義烏托邦裏，仍有廠商不夠了解開源，沒有提供可安裝的驅動程序。有時候，一些公司為驅動程序提供開源代碼，而需要你下載代碼、修補內核、編譯並手動安裝。</p><p>這種發佈方式和在 kmod 系統之外安裝打包的驅動程序擁有同樣的缺點：對內核的更新會破壞驅動程序，因為每次更換新的內核時都必須手動將其重新集成到內核中。</p><p>令人高興的是，這種事情變得少見了，因為 Linux 內核團隊在呼籲公司們與他們交流方面做得很好，並且公司們最終接受了開源不會很快消失的事實。但仍有新奇的或高度專業的設備僅提供了內核補丁。</p><p>官方上，對於你如何編譯內核以使包管理器參與到升級系統如此重要的部分中，發行版有特定的習慣。這裏有太多的包管理器，所以無法一一涵蓋。舉一個例子，當你使用 Fedora 上的工具例如 <code>rpmdev</code> 或 <code>build-essential</code>，Debian 上的 <code>devscripts</code>。</p><p>首先，像通常那樣，找到你正在運行內核的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -r</span></span></code></pre></div>',11)),n("p",null,[s[22]||(s[22]=i("在大多數情況下，如果你還沒有升級過內核那麼可以試試升級一下內核。搞定之後，也許你的問題就會在最新發布的內核中解決。如果你嘗試後發現不起作用，那麼你應該下載正在運行內核的源碼。大多數發行版提供了特定的命令來完成這件事，但是手動操作的話，可以在 ",-1)),a(t,{href:"https://www.kernel.org/"},{default:e(()=>[...s[21]||(s[21]=[i("kernel.org",-1)])]),_:1}),s[23]||(s[23]=i(" 上找到它的源代碼。",-1))]),s[43]||(s[43]=l(`<p>你必須下載內核所需的任何補丁。有時候，這些補丁對應具體的內核版本，因此請謹慎選擇。</p><p>通常，或至少在人們習慣於編譯內核的那時，都是拿到源代碼並對 <code>/usr/src/linux</code> 打上補丁。</p><p>解壓內核源碼並打上需要的補丁：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /usr/src/linux</span></span>
<span class="line"><span>$ bzip2 --decompress linux-5.2.4.tar.bz2</span></span>
<span class="line"><span>$ cd  linux-5.2.4</span></span>
<span class="line"><span>$ bzip2 -d ../patch*bz2</span></span></code></pre></div><p>補丁文件也許包含如何使用的教程，但通常它們都設計成在內核源碼樹的頂層可用來執行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ patch -p1 &lt; patch*example.patch</span></span></code></pre></div><p>當內核代碼打上補丁後，你可以繼續使用舊的配置來對打了補丁的內核進行配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make oldconfig</span></span></code></pre></div><p><code>make oldconfig</code> 命令有兩個作用：它繼承了當前的內核配置，並且允許你配置補丁帶來的新的選項。</p><p>你或許需要運行 <code>make menuconfig</code> 命令，它啓動了一個基於 ncurses 的菜單界面，列出了新的內核所有可能的選項。整個菜單可能看不過來，但是它是以舊的內核配置為基礎的，你可以遍歷菜單並且禁用掉你沒有或不需要的硬件模組。另外，如果你知道自己有一些硬件沒有包含在當前的配置中，你可以選擇構建它，當作模組或者直接嵌入內核中。理論上，這些並不是必要的，因為你可以猜想，當前的內核運行良好只是缺少了補丁，當使用補丁的時候可能已經激活了所有設備所必要的選項。</p><p>下一步，編譯內核和它的模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make bzImage</span></span>
<span class="line"><span>$ make modules</span></span></code></pre></div><p>這會產生一個叫作 <code>vmlinuz</code> 的文件，它是你的可引導內核的壓縮版本。保存舊的版本並在 <code>/boot</code> 文件夾下替換為新的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mv /boot/vmlinuz /boot/vmlinuz.nopatch</span></span>
<span class="line"><span>$ sudo cat arch/x86_64/boot/bzImage &gt; /boot/vmlinuz</span></span>
<span class="line"><span>$ sudo mv /boot/System.map /boot/System.map.stock</span></span>
<span class="line"><span>$ sudo cp System.map /boot/System.map</span></span></code></pre></div><p>到目前為止，你已經打上了補丁並且編譯了內核和它的模組，你安裝了內核，但你並沒有安裝任何模組。那就是最後的步驟：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo make modules_install</span></span></code></pre></div><p>新的內核已經就位，並且它的模組也已經安裝。</p><p>最後一步是更新你的引導程序，為了讓你的計算機在加載 Linux 內核之前知道它的位置。GRUB 引導程序使這一過程變得相當簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo grub2-mkconfig</span></span></code></pre></div><h3 id="現實生活中的編譯" tabindex="-1">現實生活中的編譯 <a class="header-anchor" href="#現實生活中的編譯" aria-label="Permalink to “現實生活中的編譯”">​</a></h3><p>當然，現在沒有人手動執行這些命令。相反的，參考你的發行版，尋找發行版維護人員使用的開發者工具集修改內核的説明。這些工具集可能會創建一個集成所有補丁的可安裝軟件包，告訴你的包管理器來升級並更新你的引導程序。</p><h3 id="內核" tabindex="-1">內核 <a class="header-anchor" href="#內核" aria-label="Permalink to “內核”">​</a></h3><p>操作系統和內核都是玄學，但要理解構成它們的組件並不難。下一次你看到某個技術無法應用在 Linux 上時，深呼吸，調查可用的驅動程序，尋找一條捷徑。Linux 比以前簡單多了——包括內核。</p><hr>`,24)),n("p",null,[s[25]||(s[25]=i("via: ",-1)),a(t,{href:"https://opensource.com/article/19/8/linux-kernel-21st-century"},{default:e(()=>[...s[24]||(s[24]=[i("https://opensource.com/article/19/8/linux-kernel-21st-century",-1)])]),_:1})]),n("p",null,[s[30]||(s[30]=i("作者：",-1)),a(t,{href:"https://opensource.com/users/seth"},{default:e(()=>[...s[26]||(s[26]=[i("Seth Kenlon",-1)])]),_:1}),s[31]||(s[31]=i(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[27]||(s[27]=[i("lujun9972",-1)])]),_:1}),s[32]||(s[32]=i(" 譯者：",-1)),a(t,{href:"https://github.com/LuuMing"},{default:e(()=>[...s[28]||(s[28]=[i("LuMing",-1)])]),_:1}),s[33]||(s[33]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[29]||(s[29]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[36]||(s[36]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[34]||(s[34]=[i("LCTT",-1)])]),_:1}),s[37]||(s[37]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:e(()=>[...s[35]||(s[35]=[i("Linux中國",-1)])]),_:1}),s[38]||(s[38]=i(" 榮譽推出",-1))])])}const y=p(u,[["render",g]]);export{v as __pageData,y as default};
